// Compute date range: past 7 days
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = sevenDaysAgo.toISOString();
const until = now.toISOString();

// Read configurable variables
const repo = $vars.GITHUB_REPO || 'owner/repo';
const language = ($vars.SUMMARY_LANGUAGE || 'EN').toUpperCase();

return [{
  json: {
    repo,
    since,
    until,
    language,
    since_display: sevenDaysAgo.toISOString().substring(0, 10),
    until_display: now.toISOString().substring(0, 10)
  }
}];

// Aggregate data from all three GitHub API calls
const vars = $('Init Variables').first().json;
const since = new Date(vars.since);
const until = new Date(vars.until);

// --- Commits ---
const commitsRaw = $('Fetch GitHub Commits').first().json;
const commitsArray = Array.isArray(commitsRaw) ? commitsRaw : [];
const commits = commitsArray.map(c => ({
  sha: (c.sha || '').substring(0, 7),
  message: (c.commit && c.commit.message ? c.commit.message.split('\n')[0] : 'No message').substring(0, 120),
  author: c.commit && c.commit.author ? c.commit.author.name : 'Unknown',
  date: c.commit && c.commit.author ? c.commit.author.date : ''
}));

// --- Closed Issues (exclude PRs which also appear as issues) ---
const issuesRaw = $('Fetch Closed Issues').first().json;
const issuesArray = Array.isArray(issuesRaw) ? issuesRaw : [];
const closedSince = issuesArray.filter(i => {
  if (i.pull_request) return false; // skip PRs
  const closedAt = i.closed_at ? new Date(i.closed_at) : null;
  return closedAt && closedAt >= since && closedAt <= until;
});
const issues = closedSince.map(i => ({
  number: i.number,
  title: (i.title || 'No title').substring(0, 120),
  closed_at: i.closed_at ? i.closed_at.substring(0, 10) : '',
  author: i.user ? i.user.login : 'Unknown'
}));

// --- Merged PRs ---
const prsRaw = $('Fetch Merged PRs').first().json;
const prsArray = Array.isArray(prsRaw) ? prsRaw : [];
const mergedPRs = prsArray.filter(pr => {
  if (!pr.merged_at) return false;
  const mergedAt = new Date(pr.merged_at);
  return mergedAt >= since && mergedAt <= until;
});
const prs = mergedPRs.map(pr => ({
  number: pr.number,
  title: (pr.title || 'No title').substring(0, 120),
  merged_at: pr.merged_at ? pr.merged_at.substring(0, 10) : '',
  author: pr.user ? pr.user.login : 'Unknown'
}));

// Build text blocks for the prompt
const commitLines = commits.length > 0
  ? commits.map(c => `- [${c.sha}] ${c.message} (by ${c.author})`).join('\n')
  : '- No commits this week';

const issueLines = issues.length > 0
  ? issues.map(i => `- #${i.number}: ${i.title} (closed ${i.closed_at} by ${i.author})`).join('\n')
  : '- No issues closed this week';

const prLines = prs.length > 0
  ? prs.map(pr => `- #${pr.number}: ${pr.title} (merged ${pr.merged_at} by ${pr.author})`).join('\n')
  : '- No PRs merged this week';

return [{
  json: {
    repo: vars.repo,
    period: `${vars.since_display} → ${vars.until_display}`,
    language: vars.language,
    commit_count: commits.length,
    issue_count: issues.length,
    pr_count: prs.length,
    commit_lines: commitLines,
    issue_lines: issueLines,
    pr_lines: prLines
  }
}];

// Build the Claude prompt based on language setting
const data = $input.first().json;
const lang = data.language === 'FR' ? 'French' : 'English';

const systemPrompt = `You are a technical writer that creates clear, engaging weekly development summaries for software teams. Write in ${lang}.`;

const userPrompt = `Generate a weekly development summary for the repository "${data.repo}" covering the period ${data.period}.

Here is the raw activity data:

## Commits (${data.commit_count} total)
${data.commit_lines}

## Closed Issues (${data.issue_count} total)
${data.issue_lines}

## Merged Pull Requests (${data.pr_count} total)
${data.pr_lines}

Write a concise narrative summary (3-5 paragraphs) that:
1. Highlights the most important work accomplished this week
2. Groups related commits/PRs into themes when possible
3. Calls out any notable bug fixes or closed issues
4. Ends with a brief outlook or observation

Use Markdown formatting. Keep it under 600 words. Write in ${lang}.`;

return [{
  json: {
    ...data,
    system_prompt: systemPrompt,
    user_prompt: userPrompt
  }
}];

// Extract summary from Claude response and format Discord message
const claudeResponse = $input.first().json;
const data = $('Build Claude Prompt').first().json;

let summary = '';
if (claudeResponse.content && claudeResponse.content.length > 0) {
  summary = claudeResponse.content[0].text || 'No summary generated.';
} else if (claudeResponse.error) {
  summary = `Error from Claude API: ${claudeResponse.error.message || JSON.stringify(claudeResponse.error)}`;
} else {
  summary = 'No summary generated.';
}

// Discord embed format
const discordPayload = {
  username: 'GitHub Dev Summary Bot',
  avatar_url: 'https://github.githubassets.com/images/modules/logos_page/GitHub-Mark.png',
  embeds: [
    {
      title: `Weekly Dev Summary — ${data.repo}`,
      description: summary.substring(0, 4000),
      color: 5814783,
      fields: [
        {
          name: 'Period',
          value: data.period,
          inline: true
        },
        {
          name: 'Commits',
          value: String(data.commit_count),
          inline: true
        },
        {
          name: 'Closed Issues',
          value: String(data.issue_count),
          inline: true
        },
        {
          name: 'Merged PRs',
          value: String(data.pr_count),
          inline: true
        },
        {
          name: 'Language',
          value: data.language,
          inline: true
        }
      ],
      footer: {
        text: 'Powered by Claude (claude-sonnet-4-20250514) via n8n'
      },
      timestamp: new Date().toISOString()
    }
  ]
};

return [{ json: discordPayload }];
